    vector<int> dist(MAXN, -1);
    vector<bool> vis(MAXN, false);
    vector<vector<pair<int, int>>> go(MAXN);
    for (int i = 1; i <= m; i++) {
        cin >> l >> r >> w;
        go[l].push_back(make_pair(r + 1, w));
        go[r + 1].push_back(make_pair(l, -w));
